// Parse JSON from LLM output, handling code fences, bracket confusion, etc.
const raw = $input.item.json.text || $input.item.json.response || JSON.stringify($input.item.json);

// Helper: try to parse, return null on failure
function tryParse(str) {
  try { return JSON.parse(str); } catch { return null; }
}

// Step 1: Strip markdown code blocks if present
let cleaned = raw.trim();
cleaned = cleaned.replace(/^```(?:json)?\s*\n?/i, '');
cleaned = cleaned.replace(/\n?```\s*$/i, '');
cleaned = cleaned.trim();

// Step 2: Extract JSON object if there's surrounding text
if (!cleaned.startsWith('{')) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) cleaned = match[0];
}

// Step 3: Try parsing as-is first
let parsed = tryParse(cleaned);
if (parsed) return [{ json: { output: parsed } }];

// Step 4: Fix LLM bracket/brace confusion
// LLMs sometimes use [ ] instead of { } for objects inside arrays
let fixed = cleaned;

// Fix opening brackets used as braces: ["key": → {"key":
fixed = fixed.replace(/\[\s*"(\w+)"\s*:/g, '{"$1":');

// Fix closing brackets used as braces: "], { or "], [ → "}, { or "}, [
fixed = fixed.replace(/"\]\s*,/g, '"},');

// Fix closing bracket at end of array: "]} → "}]
fixed = fixed.replace(/"\]\s*\]/g, '"}]');

parsed = tryParse(fixed);
if (parsed) return [{ json: { output: parsed } }];

// Step 5: Collapse newlines and try again (with bracket fixes)
let collapsed = fixed
  .split('\n')
  .map(line => line.trim())
  .join(' ')
  .replace(/\s+/g, ' ');

parsed = tryParse(collapsed);
if (parsed) return [{ json: { output: parsed } }];

// Step 6: Remove trailing commas
let noTrailing = collapsed.replace(/,\s*([}\]])/g, '$1');
parsed = tryParse(noTrailing);
if (parsed) return [{ json: { output: parsed } }];

// Step 7: Last resort - extract with greedy regex and apply all fixes
const jsonMatch = raw.match(/\{[\s\S]*\}/);
if (jsonMatch) {
  let lastTry = jsonMatch[0]
    .split('\n')
    .map(line => line.trim())
    .join(' ')
    .replace(/\s+/g, ' ');
  // Apply bracket fixes
  lastTry = lastTry.replace(/\[\s*"(\w+)"\s*:/g, '{"$1":');
  lastTry = lastTry.replace(/"\]\s*,/g, '"},');
  lastTry = lastTry.replace(/"\]\s*\]/g, '"}]');
  lastTry = lastTry.replace(/,\s*([}\]])/g, '$1');
  parsed = tryParse(lastTry);
  if (parsed) return [{ json: { output: parsed } }];

  throw new Error('JSON parse failed after cleanup. First 500 chars: ' + lastTry.substring(0, 500));
}
